import test from 'node:test';import assert from 'node:assert/strict';
import {create,validate,initial,assess,simulate,stateAt,edges} from './engine.js';
import {switchNetwork,toggleLink,placement,differences,positions,validateBundle,portable,parse,markdown} from './plans.js';
const count=r=>r.final.filter(Boolean).length;
test('mixed partners preserve every person’s degree while connecting formerly separate groups',()=>{const a=create(),b=switchNetwork(a,'mixed');assert.equal(edges(a).length,30);assert.equal(edges(b).length,30);for(const s of [a,b])assert.deepEqual(assess(s,initial(s)).map(x=>x.neighbours.length),Array(12).fill(5));const reach=s=>{const seen=new Set([0]);for(let n=0;n<12;n++)edges(s).forEach(([a,b])=>{if(seen.has(a)||seen.has(b)){seen.add(a);seen.add(b);}});return seen.size;};assert.equal(reach(a),6);assert.equal(reach(b),12);assert.equal(edges(switchNetwork(a,'hub')).length,11);});
test('fixed pilot and utility assumptions can produce different adoption at the same network degree',()=>{const a={...create(),seeds:[0,1,2]},b=switchNetwork(a,'mixed');assert.equal(count(simulate(a)),6);assert.equal(count(simulate(b)),3);assert.deepEqual(differences(a,b),['connections']);assert.deepEqual(a.seeds,b.seeds);});
test('equal totals can hide disjoint adoption cohorts',()=>{const a=simulate({...create(),seeds:[0,1,2]}),b=simulate({...create(),seeds:[6,7,8]});assert.equal(count(a),6);assert.equal(count(b),6);assert.ok(a.final.every((x,i)=>x!==b.final[i]));});
test('pilot placement recipes retain size and assumptions, and hub position has a causal effect',()=>{const s=switchNetwork({...create(),seeds:[1]},'hub');assert.equal(count(simulate(s)),1);const central=placement(s,'connected');assert.deepEqual(central.seeds,[0]);assert.equal(count(simulate(central)),12);for(const kind of ['spread','connected','concentrate']){const next=placement({...s,seeds:[1,2,3]},kind);assert.equal(next.seeds.length,3);assert.deepEqual(edges(next),edges(s));assert.equal(next.benefit,s.benefit);assert.equal(next.hold,s.hold);}assert.deepEqual(placement(s,'spread',4).seeds,[0,6,1,7]);});
test('custom link changes are independent, undirected and preserve the layout they came from',()=>{const s=switchNetwork(create(),'mixed'),before=structuredClone(s),next=toggleLink(s,0,3);assert.deepEqual(s,before);assert.equal(next.links.length,31);assert.deepEqual(positions(next),positions(s));assert.equal(toggleLink(next,3,0).links.length,30);assert.throws(()=>toggleLink(next,2,2));for(const links of [[[0,1],[1,0]],[[0,0]],[[0,12]],[[.2,3]]])assert.throws(()=>validate({...s,network:'custom',links}));});
test('isolated people receive zero coordination utility and still respect personal value and friction',()=>{const s={...create(),network:'custom',links:[],seeds:[],benefit:2,switching:1.5};const rows=assess(s,initial(s));rows.forEach(r=>{assert.equal(r.oldValue,0);assert.equal(r.newValue,r.personal);assert.ok(Number.isFinite(r.gain));assert.equal(r.neighbours.length,0);});assert.equal(rows[0].next,false);assert.equal(rows[1].next,true);});
test('repeating cycles remain phase-correct when compared at later matching rounds',()=>{const s={...create(),network:'custom',links:[[0,1]],seeds:[0],hold:false,benefit:0,switching:0},r=simulate(s);assert.equal(r.status,'cycle');assert.equal(r.cycleLength,2);for(let i=1;i<20;i++)assert.deepEqual(stateAt(r,i),stateAt(r,i+2));assert.notDeepEqual(stateAt(r,10),stateAt(r,11));const stable=simulate(create());assert.deepEqual(stateAt(stable,20),stable.final);});
test('legacy bridge plans retain exact edges and trajectories, and comparisons name every changed assumption',()=>{const legacy={seeds:[0,1],benefit:2,coordination:8,switching:1.5,bridge:true,compatibility:0,hold:true};const modern={...legacy,network:'groups'};assert.deepEqual(simulate(legacy),simulate(modern));assert.equal(edges(legacy).length,32);const b=validateBundle({s:legacy,baseline:modern});assert.deepEqual(b.s,legacy);assert.deepEqual(differences({...modern,benefit:3,hold:false,seeds:[0,6]},modern),['pilot location','standalone benefit','pilot commitment']);});
test('portable experiments preserve custom links, fixed baseline, inspection and decisions; malformed imports are rejected',()=>{const s=toggleLink(create(),0,6),bundle=validateBundle({s,baseline:create(),round:1,selected:6,mode:'inspect',decision:'Try a bridge with the same people before enlarging the pilot.'});const text=portable(bundle);assert.deepEqual(parse(text),bundle);assert.match(markdown(bundle),/Try a bridge/);assert.match(markdown(bundle),/Pinned at same round/);for(const bad of [x=>x.s.links.push([0,6]),x=>x.s.links.push([1,1]),x=>x.baseline.benefit=NaN,x=>x.selected=20]){const broken=structuredClone(bundle);bad(broken);assert.throws(()=>validateBundle(broken));assert.equal(portable(bundle),text);}});
